import{_ as r,a0 as d,w as s,s as l,ao as a,I as p,x as o,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"如何在 Ubuntu 中再次登录时还原上次运行的应用 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中再次登录时还原上次运行的应用 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中再次登录时还原上次运行的应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中再次登录时还原上次运行的应用 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150119 How to Remember and Restore Running Applications on Next Logon","title":"如何在 Ubuntu 中再次登录时还原上次运行的应用","tag":"201504","desc":""},"relativePath":"201504/20150119 How to Remember and Restore Running Applications on Next Logon.md","filePath":"[post].md"}'),u={name:"201504/20150119 How to Remember and Restore Running Applications on Next Logon.md"};function c(g,e,m,b,f,x){const t=d("Link");return s(),l("div",null,[e[13]||(e[13]=a(`<h1 id="如何在-ubuntu-中再次登录时还原上次运行的应用" tabindex="-1">如何在 Ubuntu 中再次登录时还原上次运行的应用 <a class="header-anchor" href="#如何在-ubuntu-中再次登录时还原上次运行的应用" aria-label="Permalink to “如何在 Ubuntu 中再次登录时还原上次运行的应用”">​</a></h1><p>在你的 Ubuntu 里，如果你需要处理一些工作，你并不需要关闭正运行着的那些应用，只需要管理一下窗口，并打开那些工作需要的应用就行。然而，如果你需要离开处理些别的事情或你的机器电量低使得你必须马上关闭电脑，这些程序可能就需要关闭终止了。不过幸运的是，你可以让 Ubuntu 记住所有你正运行的应用并在你下一次登录时还原它们。</p><p>###自动保存会话</p><p>现在，为了让我们的 Ubuntu 记住当前会话中正运行的应用并在我们下一次登录时还原它们，我们将会使用到 <code>dconf-editor</code>。这个工具代替了前一个 Ubuntu 版本里安装的 <code>gconf-editor</code>，但默认情况下现在这个 Ubuntu 版本(注：这里指的是 Ubuntu 14.04 LTS) 并没有安装。为了安装 <code>dconf-editor</code>， 你需要运行 <code>sudo apt-get install dconf-editor</code>命令：</p><pre><code>$ sudo apt-get install dconf-tools
</code></pre><p>一旦 <code>dconf-editor</code> 安装完毕，你就可以从应用菜单（注：这里指的是 Unity Dash）里打开它，或者你可以通过直接在终端里运行，或使用 <code>alt+f2</code> 运行下面的命令来启动它:</p><pre><code>$ dconf-editor
</code></pre><p>在 “dconf Editor” 窗口中，在左边窗格里点击临近 &quot;org&quot; 的右箭头来展开这个选项的分支。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/dconf-editor-clicking-org-300x146.png" alt="Dconf Editor Apps, org"></p><p>然后在 “org” 下，点击临近 “gnome” 的右箭头。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/dconf-editor-clicking-gnome.png" alt="dconf editor clicking gnome"></p><p>接着在 “gnome” 下点击 “gnome-session”。在右边窗格里，选择 “auto-save-session” 选项框并将它开启。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/dconf-editor_selecting_auto_save_session.png" alt="dconf-editor selecting auto save session"></p><p>在你确认对刚才的选项打钩之后，点击默认情况下位于窗口左上角的关闭按钮(X)来关闭 “Dconf Editor”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/dconf-editor_closing_dconf_editor.png" alt="dconf-editor closing dconf editor"></p><p>在你登出并再登录回来时，所有你正运行的应用就可以被还原了。</p><p>欢呼吧，我们已经成功地配置了我们的 Ubuntu 14.04 LTS &quot;Trusty&quot; 来自动记住我们上一次会话中正在运行的应用。</p><p>除了关机后恢复应用之外，还可以通过休眠来达成类似的功能。</p><p>###休眠功能</p><p>现在，在这个教程里，我们也将学会 <strong>如何在 Ubuntu 14.04 LTS 里开启休眠功能</strong> :</p><p>在开始之前，在键盘上按 <code>Ctrl+Alt+T</code> 来开启终端。在它开启以后，运行：</p><pre><code>sudo pm-hibernate
</code></pre><p>在你的电脑关闭后，再重新开启它。这时，你开启的应用被重新打开了吗？如果休眠功能没有发挥作用，请检查你的交换分区大小，它至少要和你可用 RAM 大小相当。</p><p>你可以在系统监视器里查看你的交换分区大小，系统监视器可以通过在应用菜单或在终端里运行下面的命令来开启：</p><pre><code>$ gnome-system-monitor
</code></pre><h4 id="在系统托盘里启用休眠功能" tabindex="-1">在系统托盘里启用休眠功能: <a class="header-anchor" href="#在系统托盘里启用休眠功能" aria-label="Permalink to “在系统托盘里启用休眠功能:”">​</a></h4><p>系统托盘里面的会话指示器现在使用 logind 而不是 upower 了。默认情况下，在 upower 和 logind 中，休眠菜单都被禁用了。</p><p>为了开启它的休眠菜单，依次运行下面的命令来编辑配置文件：</p><pre><code>sudo -i

cd /var/lib/polkit-1/localauthority/50-local.d/

gedit com.ubuntu.enable-hibernate.pkla
</code></pre><p><strong>提示：假如对你来说，这个配置文件并没有起到作用，请替换上面代码中的 /var/lib 为 /etc 来试试另一个配置文件</strong></p><p>复制并粘贴下面的代码到文件中并保存：</p><pre><code>[Re-enable hibernate by default in upower]
 Identity=unix-user:*
 Action=org.freedesktop.upower.hibernate
 ResultActive=yes

[Re-enable hibernate by default in logind]
 Identity=unix-user:*
 Action=org.freedesktop.login1.hibernate
 ResultActive=yes
</code></pre><p>重启你的电脑就可以了。</p><h4 id="当你盖上笔记本的后盖时-让它休眠" tabindex="-1">当你盖上笔记本的后盖时，让它休眠: <a class="header-anchor" href="#当你盖上笔记本的后盖时-让它休眠" aria-label="Permalink to “当你盖上笔记本的后盖时，让它休眠:”">​</a></h4><ol><li><p>通过下面的命令编辑文件 “/etc/systemd/logind.conf” :</p><pre><code> $ sudo nano /etc/systemd/logind.conf
</code></pre></li><li><p>将 <strong>#HandleLidSwitch=suspend</strong> （挂起）这一行改为 <strong>HandleLidSwitch=hibernate</strong> （休眠）并保存文件；</p></li><li><p>运行下面的命令或重启你的电脑来应用更改:</p><pre><code> $ sudo restart systemd-logind
</code></pre></li></ol><p>就是这样。 成功了吗？现在我们设置了 dconf 并开启了休眠功能 😃 这样，无论你是关机还是直接合上笔记本盖子，你的 Ubuntu 将能够完全记住你开启的应用和窗口了。</p><hr>`,37)),p("p",null,[e[1]||(e[1]=o("via: ",-1)),n(t,{href:"http://linoxide.com/ubuntu-how-to/remember-running-applications-ubuntu/"},{default:i(()=>[...e[0]||(e[0]=[o("http://linoxide.com/ubuntu-how-to/remember-running-applications-ubuntu/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=o("作者：",-1)),n(t,{href:"http://linoxide.com/author/arunp/"},{default:i(()=>[...e[2]||(e[2]=[o("Arun Pyasi",-1)])]),_:1}),e[6]||(e[6]=o(" 译者：",-1)),n(t,{href:"https://github.com/FSSlc"},{default:i(()=>[...e[3]||(e[3]=[o("FSSlc",-1)])]),_:1}),e[7]||(e[7]=o(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原创翻译，",-1)),n(t,{href:"http://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[o("Linux中国",-1)])]),_:1}),e[12]||(e[12]=o(" 荣誉推出",-1))])])}const w=r(u,[["render",c]]);export{_ as __pageData,w as default};
